def transform(grid):
    import collections
    flat = [cell for row in grid for cell in row]
    bg = collections.Counter(flat).most_common(1)[0][0]
    rows, cols = len(grid), len(grid[0])
    output = [[bg] * cols for _ in range(rows)]

    last_col = cols - 1
    for r in range(rows):
        if grid[r][last_col] != bg:
            val = grid[r][last_col]
            # The special pixel triggers a pattern in rows r-1, r, r+1
            for rr in range(max(0, r-1), min(rows, r+2)):
                dist = abs(rr - r)
                if dist % 2 == 0: # Center or aligned rows (phase 0)
                    # Start with val at even columns
                    for c in range(cols):
                        output[rr][c] = val if c % 2 == 0 else bg
                else: # Offset rows (phase 1)
                    # Start with bg at even columns
                    for c in range(cols):
                        output[rr][c] = bg if c % 2 == 0 else val
    return output
